import{_ as o,o as e,c as r,ag as n}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"데카르트의 실체이원론","slug":"데카르트의-실체이원론","link":"#데카르트의-실체이원론","children":[]},{"level":2,"title":"방법적 회의와 코기토","slug":"방법적-회의와-코기토","link":"#방법적-회의와-코기토","children":[]},{"level":2,"title":"자아의 본성 — 사유함","slug":"자아의-본성-—-사유함","link":"#자아의-본성-—-사유함","children":[]},{"level":2,"title":"이원론 논증 1 — 의심가능성 논증","slug":"이원론-논증-1-—-의심가능성-논증","link":"#이원론-논증-1-—-의심가능성-논증","children":[]},{"level":2,"title":"이원론 논증 2 — 상상가능성(conceivability) 논증","slug":"이원론-논증-2-—-상상가능성-conceivability-논증","link":"#이원론-논증-2-—-상상가능성-conceivability-논증","children":[]},{"level":2,"title":"이원론 논증 3 — 단순성 논증과 영혼불멸론","slug":"이원론-논증-3-—-단순성-논증과-영혼불멸론","link":"#이원론-논증-3-—-단순성-논증과-영혼불멸론","children":[]},{"level":2,"title":"엘리자베스 공주의 상호작용 비판","slug":"엘리자베스-공주의-상호작용-비판","link":"#엘리자베스-공주의-상호작용-비판","children":[]},{"level":2,"title":"흄의 자아 다발이론 — 대안적 시각","slug":"흄의-자아-다발이론-—-대안적-시각","link":"#흄의-자아-다발이론-—-대안적-시각","children":[]},{"level":2,"title":"비물리적 실체는 정당화되는가","slug":"비물리적-실체는-정당화되는가","link":"#비물리적-실체는-정당화되는가","children":[]}],"relativePath":"philosophy/Philosophy-of-Mind/02. 데카르트의 실체이원론.md","filePath":"philosophy/Philosophy-of-Mind/02. 데카르트의 실체이원론.md"}'),i={name:"philosophy/Philosophy-of-Mind/02. 데카르트의 실체이원론.md"};function a(l,t,d,s,u,h){return e(),r("div",null,[...t[0]||(t[0]=[n('<h2 id="데카르트의-실체이원론" tabindex="-1">데카르트의 실체이원론 <a class="header-anchor" href="#데카르트의-실체이원론" aria-label="Permalink to &quot;데카르트의 실체이원론&quot;">​</a></h2><p>데카르트(1596~1650)의 『성찰』 부제는 &quot;여기서 신의 존재 및 인간 영혼의 불멸성이 증명됨&quot;이다. <strong>실체이원론(substance dualism)</strong>의 핵심 주장은 세 갈래로 나뉜다.</p><ol><li>마음과 육체는 동일하지 않으며 근본적으로 다른 종류의 <strong>실체(substance)</strong>다 — 마음의 본성은 <strong>사유(thought)</strong>, 육체의 본성은 공간에 위치한 <strong>연장(extension)</strong>.</li><li>사람은 마음과 육체의 결합체다 — &quot;선원이 배 안에 있는 것처럼 내가 신체 속에 있을 뿐만 아니라, 신체와 아주 밀접하게 결합되어 있고, 거의 혼합되어 있어서 신체와 일체를 이루고 있음.&quot;</li><li>마음과 육체는 서로 <strong>인과적으로 상호작용</strong>한다 — 정신은 뇌(특히 공통감각이 있는 부분)로부터만 영향을 받는다고 봄. 이 상호작용의 원리를 <strong>심신인과(mental causation)</strong>라 부르며, 이를 설명하는 것은 심리철학의 핵심 문제 중 하나로 남는다.</li></ol><p>길버트 라일(Gilbert Ryle)은 『The Concept of Mind』(1949)에서 데카르트의 이원론을 &quot;공식 원리(official doctrine)&quot;라 부르며, 그 실체로서의 영혼을 <strong>&quot;기계 안의 유령(the ghost in the machine)&quot;</strong>이라 조롱했다. 이 강의의 초점은 위 (1), 즉 마음과 육체가 별개의 실체라는 주장에 대한 데카르트의 논증이다.</p><h2 id="방법적-회의와-코기토" tabindex="-1">방법적 회의와 코기토 <a class="header-anchor" href="#방법적-회의와-코기토" aria-label="Permalink to &quot;방법적 회의와 코기토&quot;">​</a></h2><p>데카르트는 제1성찰에서 외부 대상의 존재를 의심 가능한 것으로 만든다(&quot;꿈으로부터의 논증&quot;, 유능한 기만자 가설). 제2성찰은 이 회의 아래에서도 확실한 것이 하나라도 있는지 검토한다.</p><p><strong>코기토(cogito) 논증</strong>의 구조는 다음과 같다.</p><blockquote><p>유능한 기만자는 X가 없음에도 불구하고 X가 있다고 생각하게끔 나를 속일 수 있다. 따라서 X가 존재한다는 것은 확실하지 않다.</p></blockquote><p>이 형식은 책상, 옆 사람, 심지어 나의 팔다리에도 적용된다. 하지만 &quot;X&quot; 자리에 &quot;나&quot;를 넣으면 — &quot;유능한 기만자는 내가 없음에도 내가 존재한다고 믿게끔 속일 수 있다&quot; — 는 명백한 넌센스가 된다. 나를 속이려면 애초에 내가 존재해야 하기 때문이다. (참고로 잘 알려진 &quot;나는 생각한다, 그러므로 나는 존재한다&quot;는 『성찰』이 아니라 『방법서설』의 문구다. 여기서 정말로 &quot;내가 존재한다&quot;는 확실성이 따라 나오는지는 논란거리로 남는다.)</p><h2 id="자아의-본성-—-사유함" tabindex="-1">자아의 본성 — 사유함 <a class="header-anchor" href="#자아의-본성-—-사유함" aria-label="Permalink to &quot;자아의 본성 — 사유함&quot;">​</a></h2><p>철학자들은 어떤 것 X의 <strong>본성(nature, essence)</strong>을 &quot;X가 X이기 위해 반드시 가져야 하는 속성(N이 X의 본성이다 ⇔ X가 N을 갖는 것이 필연적이다)&quot;으로 규정한다. 데카르트는 신체에 속한다고 여겨지는 속성은 모두 의심 가능하지만, &quot;사유한다는 것&quot;만은 의심 중에도 남는다고 보아 <strong>나의 본성은 사유함</strong>이라 결론짓는다. 여기서 &quot;사유&quot;는 일상어보다 넓은 뜻으로, 의심하고 이해하고 긍정·부정하고 의욕하고 상상하고 감각하는 것 전부를 포함한다.</p><p>다만 이 추론에는 의문이 남는다.</p><blockquote><p>P. 내가 생각하고 있을 때에만 나는 내가 존재한다고 확신할 수 있다.<br> C. 따라서 필연적으로, 내가 생각하고 있을 때에만 나는 존재한다(사유가 나의 본성이다).</p></blockquote><p>이는 &quot;내 애인이 애정을 표현할 때에만 나는 애인의 사랑을 확신할 수 있다. 따라서 애정 표현이 사랑의 본성이다&quot;라는 논증과 같은 형태다 — <strong>확신의 조건</strong>과 <strong>본성</strong>을 혼동하는 오류일 수 있다는 것.</p><h2 id="이원론-논증-1-—-의심가능성-논증" tabindex="-1">이원론 논증 1 — 의심가능성 논증 <a class="header-anchor" href="#이원론-논증-1-—-의심가능성-논증" aria-label="Permalink to &quot;이원론 논증 1 — 의심가능성 논증&quot;">​</a></h2><p>제2성찰에 이미 등장하는 논증(엄밀히는 이원론을 증명하려는 의도는 아니었음):</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>나의 육체의 존재는 의심될 수 있다</td></tr><tr><td>P2</td><td>나의 존재는 의심될 수 없다</td></tr><tr><td>C</td><td>따라서 나 ≠ 나의 육체</td></tr></tbody></table><p>이 논증은 <strong>라이프니츠의 법칙(Leibniz&#39;s law)</strong> — 동일한 것은 반드시 같은 속성을 가져야 한다(a가 F이고 b가 F가 아니면 a≠b) — 을 전제한다.</p><p><strong>반론</strong>: 라이프니츠의 법칙은 &quot;…라고 생각한다&quot;, &quot;…을 의심한다&quot;, &quot;…을 안다&quot; 같은 동사가 포함된 <strong>내포적 맥락(intensional context)</strong>에서는 예외를 허용하는 것처럼 보인다.</p><blockquote><p>나는 RM이 잘생겼다고 생각한다. 나는 김남준이 잘생겼다고 생각하지 않는다. 따라서 RM ≠ 김남준?</p></blockquote><p>이는 명백히 부당한 추론이다(RM=김남준). 생각·의심은 대상에 직접 관여하는 것이 아니라 그 대상에 대한 <strong>개념(concept)</strong>을 매개로 하기 때문에, 같은 대상을 서로 다른 두 개념으로 생각하면서 그 둘이 같은 대상을 가리키는지 모를 수 있다. 그렇다면 데카르트의 의심가능성 논증이 실제로 보여주는 것도 기껏해야 &quot;나&quot;라는 개념과 &quot;나의 육체&quot;라는 개념이 다르다는 것뿐이지 않은가 — 라는 반론이 성립한다.</p><h2 id="이원론-논증-2-—-상상가능성-conceivability-논증" tabindex="-1">이원론 논증 2 — 상상가능성(conceivability) 논증 <a class="header-anchor" href="#이원론-논증-2-—-상상가능성-conceivability-논증" aria-label="Permalink to &quot;이원론 논증 2 — 상상가능성(conceivability) 논증&quot;">​</a></h2><p>제6성찰의 논증:</p><blockquote><p>&quot;내가 명석판명하게 인식하는 것은 모두 내가 이것을 인식하는 대로 신에 의해 만들어질 수 있음을 알고 있기 때문에, 어떤 것을 다른 것 없이 명석판명하게 인식하기만 하면, 어떤 것이 다른 것과 상이하다고 충분히 확신할 수 있다.&quot;</p></blockquote><p>현대적으로 재구성하면:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>나는 내가 육체 없이 존재하는 것을 모순 없이 생각할 수 있다</td></tr><tr><td>P2</td><td>내가 어떤 것을 모순 없이 생각할 수 있다면, 그것은 논리적으로 가능하다</td></tr><tr><td>P3</td><td>따라서 내가 육체와 분리되는 것은 논리적으로 가능하다</td></tr><tr><td>P4</td><td>(숨은 전제) 내가 육체와 분리되는 것이 논리적으로 가능하다면, 나는 육체와 동일하지 않다</td></tr><tr><td>C</td><td>따라서 나는 육체와 동일하지 않다</td></tr></tbody></table><p>타당한 논증이지만 건전한가는 별개다.</p><ul><li><strong>P4에 대한 반론</strong>: &quot;내가 김태희와 부부인 것&quot;은 논리적으로 가능하지만, 그렇다고 실제로 둘이 부부라는 것은 따라 나오지 않는다. 다만 <strong>동일성</strong>은 특수해서, 동일성 명제는 항상 필연적이라는 원리(<strong>동일성의 필연성(necessity of identity)</strong>)가 있다 — 즉 두 대상이 실제로 동일하다면 그것들이 분리되는 것은 애초에 논리적으로 불가능해야 한다는 반론.</li><li><strong>P2에 대한 반론</strong>: &quot;RM ≠ 김남준&quot;이나 &quot;물 ≠ H₂O&quot;는 모순 없이 생각(상상)할 수 있지만 실제로는 논리적으로 불가능하다(동일성이 후험적으로 발견된 필연적 진리이므로). 이런 관점에서는 &quot;모순 없이 생각할 수 있음&quot;은 개념들 사이의 관계를 보여줄 뿐, 논증이 결국 보여주는 것도 &quot;나&quot;의 개념과 &quot;육체&quot;의 개념이 다르다는 것뿐일 수 있다.</li></ul><h2 id="이원론-논증-3-—-단순성-논증과-영혼불멸론" tabindex="-1">이원론 논증 3 — 단순성 논증과 영혼불멸론 <a class="header-anchor" href="#이원론-논증-3-—-단순성-논증과-영혼불멸론" aria-label="Permalink to &quot;이원론 논증 3 — 단순성 논증과 영혼불멸론&quot;">​</a></h2><p>데카르트는 자아가 <strong>불가분적(indivisible)</strong>, 즉 단순하다는 데 주목한다 — &quot;물체는 본성상 언제나 가분적(divisible)인데 비해, 정신은 전적으로 불가분적이다.&quot;</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>나는 전적으로 불가분적이다(단순하다)</td></tr><tr><td>P2</td><td>나의 육체는 가분적이다</td></tr><tr><td>C</td><td>따라서 나 ≠ 나의 육체</td></tr></tbody></table><p>이 역시 라이프니츠의 법칙에 의존해 타당하다. P1의 근거는 손발을 잘라내도 정신에서 무언가가 제거되는 것은 아니며, 의지·감각·이해 능력이 정신의 &quot;부분&quot;인 것도 아니라는 것(참고: 두뇌 양분(brain bisection) 사례가 이 단순성 주장에 대한 현대적 반례로 논의됨).</p><p>『성찰』의 요약부에는 이 단순성으로부터 <strong>영혼불멸론</strong>을 이끌어내는 논증도 등장한다.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>어떤 것이 소멸한다는 것은 그 부분의 배열이 변화하는 것이다</td></tr><tr><td>P2</td><td>나의 영혼은 단순하다(부분으로 구성되어 있지 않다)</td></tr><tr><td>C</td><td>따라서 나의 영혼은 소멸할 수 없다</td></tr></tbody></table><h2 id="엘리자베스-공주의-상호작용-비판" tabindex="-1">엘리자베스 공주의 상호작용 비판 <a class="header-anchor" href="#엘리자베스-공주의-상호작용-비판" aria-label="Permalink to &quot;엘리자베스 공주의 상호작용 비판&quot;">​</a></h2><p>실체이원론의 세 번째 핵심 주장 — 서로 다른 본성의 두 실체가 인과적으로 상호작용한다는 것 — 은 곧바로 난점을 낳는다. 보헤미아의 <strong>엘리자베스 공주(Princess Elisabeth of Bohemia)</strong>는 데카르트에게 보낸 편지에서 이렇게 반문한다.</p><blockquote><p>&quot;어떻게 인간의 마음이, 그것이 사유하는 실체에 불과할진대, 육체적 정기를 움직여 육체적 행동을 야기하는지 설명해 주실 것을 부탁드립니다. … [물체의 운동에는] 접촉(contact)이 필요하고 … 추동하는 물체가 연장(extension)을 가질 것이 요구됩니다. 하지만 당신은 연장을 영혼으로부터 완전히 배제시켜버렸고, 접촉이라는 것은 비물리적인 것과는 양립불가능해 보입니다.&quot;</p></blockquote><p>이는 접촉에 의해서만 인과가 일어난다는 <strong>기계론적 인과관</strong>을 전제로 한 비판이다. 데카르트는 마음과 육체의 결합에 대한 &quot;원초적 개념(primitive notion)&quot;에 호소하지만, 엘리자베스는 재반박한다 — &quot;마음에 물질성과 연장을 인정하는 것이, 비물리적 실체에 물체를 움직이고 움직여질 수 있는 능력을 인정하는 것보다 더 쉬운 것 같습니다.&quot; 서로 다른 종류의 실체 사이의 인과를 어떻게 이해할 것인가는 실체이원론에 오늘날까지 따라붙는 난점이다.</p><h2 id="흄의-자아-다발이론-—-대안적-시각" tabindex="-1">흄의 자아 다발이론 — 대안적 시각 <a class="header-anchor" href="#흄의-자아-다발이론-—-대안적-시각" aria-label="Permalink to &quot;흄의 자아 다발이론 — 대안적 시각&quot;">​</a></h2><p>경험주의자 <strong>흄(Hume)</strong>은 데카르트식의 단순하고 지속적인 자아 개념 자체를 거부한다. 흄에 따르면 모든 관념(idea)은 인상(impression)에서 비롯되는데, 아무리 내성해 보아도 불변하고 지속하는 &quot;자아&quot;의 인상은 발견되지 않는다.</p><blockquote><p>&quot;내가 나의 자아라고 부를 것에 가장 깊숙이 들어가 보면, 나는 언제나 어떤 개별 지각들 … 과 마주치게 된다. 나는 잠시라도 지각 없이 나 자신을 포착할 수 없으며, 지각 외에는 아무것도 관찰할 수 없다.&quot;</p></blockquote><p>흄에게 자아란 &quot;서로 다른 지각들의 <strong>다발(bundle)</strong> 또는 집합&quot;일 뿐이며, 단일성도 시간에 걸친 동일성도 갖지 않는다. 그렇다고 자아가 아예 없다는 것은 아니고, 일종의 유용한 <strong>허구(fiction)</strong>로 간주된다.</p><h2 id="비물리적-실체는-정당화되는가" tabindex="-1">비물리적 실체는 정당화되는가 <a class="header-anchor" href="#비물리적-실체는-정당화되는가" aria-label="Permalink to &quot;비물리적 실체는 정당화되는가&quot;">​</a></h2><p>무언가의 존재를 믿는 근거는 대개 직접 관찰이거나(책상, 사과 등), 어떤 현상을 설명하기 위해 요청되는 <strong>이론적 존재자(theoretical entity)</strong>(원자, 쿼크, 병균 등)다. 후자의 정당화 방식은 <strong>최선의 설명으로의 추론(inference to the best explanation)</strong> — 어떤 가설이 경쟁 가설보다 현상 P를 더 잘 설명하면 그 가설을 참으로 받아들인다는 추론 형식(예: 세균 이론이 악령 이론보다 질병을 더 잘 설명하므로 세균의 존재를 받아들임)이다.</p><p>비물리적 자아(실체이원론)의 존재도 같은 잣대로 검토해야 한다는 것이 이 강의가 남기는 물음이다 — (1) 실체이원론이 정말로 무언가를 잘 설명하는가, 아니면 설명을 포기하는 데 가까운가, (2) 만일 설명한다면 경쟁 이론(가령 물리주의)보다 더 잘 설명하는가. 결국 비물리적 실체의 운명은 &quot;악령&quot;과 같을지, &quot;블랙홀&quot;과 같을지가 실체이원론 평가의 핵심 쟁점으로 남는다.</p>',45)])])}const p=o(i,[["render",a]]);export{c as __pageData,p as default};
